@Bean
RouterFunction<ServerResponse> routes(TaskHandler h) {
    return route()
        .GET("/api/tasks", accept(APPLICATION_JSON), h::all)
        .GET("/api/tasks/{id}", h::one)
        .POST("/api/tasks", h::create)
        .build();
}

Mono<ServerResponse> one(ServerRequest request) {
    String id = request.pathVariable("id");
    return repository.findById(id)
        .flatMap(task -> ServerResponse.ok().bodyValue(task))
        .switchIfEmpty(ServerResponse.notFound().build());
}

RouterFunction<ServerResponse> routes = route()
    .GET("/api/tasks", handler::all)
    .filter((request, next) -> {
        log.info("{} {}", request.method(), request.path());
        return next.handle(request);
    })
    .build();

Mono<ServerResponse> create(ServerRequest request) {
    return request.bodyToMono(Task.class)
        .flatMap(repository::save)
        .flatMap(saved -> ServerResponse.status(HttpStatus.CREATED)
            .bodyValue(saved));
}
